class ToastManager {
  constructor() {
    // Create the container for toasts
    this.container = document.createElement("div");
    this.container.id = "frappe-toast-container";

    this.container.className = "frappe-toast-wrapper frappe-pos-bottom-right";
    this.container.style.zIndex = "99999";

    if (document.body) {
      document.body.appendChild(this.container);
    } else {
      document.addEventListener("DOMContentLoaded", () => {
        document.body.appendChild(this.container);
      });
    }
  }

  show(options) {
    if (typeof options === "string") {
      options = { text: options };
    }

    const {
      title = "",
      text = "",
      position = "bottom-right",
      timeout = 5000,
      icon = "",
    } = options;

    this.updatePosition(position);

    const toastEl = document.createElement("div");
    toastEl.className = "frappe-toast";
    toastEl.setAttribute("role", "alert");

    const iconsMap = {
      success: `<svg class="f-icon-success" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>`,
      error: `<svg class="f-icon-error" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>`,
      info: `<svg class="f-icon-info" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>`,
      warning: `<svg class="f-icon-warning" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>`,
    };

    const iconHtml = iconsMap[icon] || icon || "";

    toastEl.innerHTML = `
            ${iconHtml ? `<div class="frappe-toast-icon">${iconHtml}</div>` : ""}
            <div class="frappe-toast-content">
                ${title ? `<div class="frappe-toast-title">${title}</div>` : ""}
                ${text ? `<div class="frappe-toast-text">${text}</div>` : ""}
            </div>
            <button class="frappe-toast-close" aria-label="Close">
                <svg fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M6 18L18 6M6 6l12 12"></path></svg>
            </button>
        `;

    this.container.appendChild(toastEl);

    const closeBtn = toastEl.querySelector(".frappe-toast-close");
    closeBtn.addEventListener("click", () => this.remove(toastEl));

    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        toastEl.classList.add("frappe-toast-show");
      });
    });

    // Auto-dismiss handler
    if (timeout) {
      setTimeout(() => {
        this.remove(toastEl);
      }, timeout);
    }
  }

  updatePosition(position) {
    const validPositions = [
      "top-right",
      "top-left",
      "top-center",
      "bottom-right",
      "bottom-left",
      "bottom-center",
    ];
    const posToApply = validPositions.includes(position)
      ? position
      : "bottom-right";
    this.container.className = `frappe-toast-wrapper frappe-pos-${posToApply}`;
  }

  remove(toastEl) {
    if (!toastEl.parentElement) return;

    toastEl.classList.remove("frappe-toast-show");

    setTimeout(() => {
      if (toastEl.parentElement) {
        toastEl.remove();
      }
    }, 300);
  }
}

const toastManager = new ToastManager();

window.toast = function (options) {
  toastManager.show(options);
};

// Expose standard helpers
window.toast.success = (text, options = {}) =>
  window.toast({ text, icon: "success", ...options });
window.toast.error = (text, options = {}) =>
  window.toast({ text, icon: "error", ...options });
window.toast.info = (text, options = {}) =>
  window.toast({ text, icon: "info", ...options });
window.toast.warning = (text, options = {}) =>
  window.toast({ text, icon: "warning", ...options });
